command:
$ErrorActionPreference="Stop"
$root=$env:FLYEXPLORER_CANONICAL_CHECKOUT
Set-Location -LiteralPath $root
& git fetch origin main work/search-v3-indexed-filename-20261008 --no-tags
if($LASTEXITCODE -ne 0){throw "fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne "387efa622f6a9ce6685e3bffb98299df0503de3c"){throw "main changed"}
if((& git rev-parse HEAD).Trim() -ne "387efa622f6a9ce6685e3bffb98299df0503de3c"){throw "baseline checkout changed"}
$old='    env["FLY_CONTENT_REGEX_VISUAL_CAPTURE_PATH"]=str(shot)'
$new='    env["FLY_CONTENT_REGEX_VISUAL_CAPTURE_PATH"]=str(base/("startup-"+args.capture+".bmp"))'+"`n"+'    env["FLY_NETWORK_VISUAL_CAPTURE_PATH"]=str(shot)'
$src=@(& git show "ffc2466be51c32c1cf7454a2df80fe4f8c3f5f99:tests/winui/test_indexed_search_gui.py")
if($LASTEXITCODE -ne 0 -or $src.Count -lt 40){throw "harness source invalid"}
$script=Join-Path $root "logs\search-v3-indexed\visual-harness-loaded-before.py"
$text=$src -join "`n"
$anchor='        wait(ready,"indexed search window",24)'
$fixed=$anchor+"`n"+'        assert ctypes.windll.user32.SetWindowPos(window.handle,0,0,0,972,720,0x0016),"fixed window resize failed"'
if(-not $text.Contains($anchor)){throw "window resize anchor missing"}
if(-not $text.Contains($old)){throw "harness capture anchor changed"}
[IO.File]::WriteAllText($script,$text.Replace($old,$new).Replace($anchor,$fixed),(New-Object Text.UTF8Encoding($false)))
try{
 & .\build.bat Release
 if($LASTEXITCODE -ne 0){throw "baseline main Release build failed"}
 $env:PYTHONPATH=Join-Path $root "tests\winui"
 & python -X utf8 $script --configuration Release --capture before
 if($LASTEXITCODE -ne 0){throw "loaded-state BEFORE capture failed"}
 Write-Host "INDEXED_VISUAL_FIXED_BEFORE=PASS"
}finally{Remove-Item -LiteralPath $script -Force -ErrorAction SilentlyContinue}
